update question_options o set body = $qb$(x - 1)(x + 2)$qb$, image_url = null from questions q where q.id = o.question_id and o.label = 'C' and q.source_ref = 'CB-0121a235' and left(md5(q.stem), 8) = 'a2db7e43';
