update question_options o set body = $qb$The measures of angle B and angle R are 32° and 96°, respectively.$qb$, image_url = null from questions q where q.id = o.question_id and o.label = 'C' and q.source_ref = 'CB-1dc7e423' and left(md5(q.stem), 8) = '5f6ab7e4';
